INSERT INTO lab_experiment_record(
    record_code, title, summary, author_id, project_id, learning_unit_id,
    template_id, template_version_id, status, version, create_time, update_time
) VALUES (
    #{recordCode}, #{title}, #{summary}, #{authorId}, #{projectId}, #{learningUnitId},
    #{templateId}, #{templateVersionId}, 'DRAFT', 1, #{createTime}, #{updateTime}
)

mapper.select:
SELECT 
FROM lab_experiment_record r

WHERE r.id = #{recordId}

mapper.sql:
AND (
    #{globalRead} = TRUE OR r.author_id = #{userId}
    OR pm.project_role IN ('OWNER', 'MAINTAINER')
    OR (r.status = 'PUBLISHED' AND pm.project_role IS NOT NULL)
    OR (pm.project_role IS NOT NULL AND EXISTS (
        SELECT 1 FROM lab_experiment_feedback visible_feedback
        WHERE visible_feedback.record_id=r.id AND visible_feedback.visibility='PROJECT_MEMBERS'
    ))
)
AND r.project_id = #{projectId}
AND r.status = #{status}
AND r.template_id = #{templateId}
AND r.author_id = #{authorId}

mapper.select:
SELECT  FROM lab_experiment_revision
WHERE record_id = #{recordId}
ORDER BY revision_no DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE lab_experiment_revision
SET status='SUBMITTED', submitted_by=#{actorId}, submitted_at=#{now},
    version=version+1, update_time=#{now}
WHERE id=#{revisionId} AND status='EDITABLE' AND version=#{expectedVersion}

UPDATE lab_experiment_record
SET status=#{toStatus}, version=version+1, update_time=#{now}
, current_revision_id=#{currentRevisionId}
, published_revision_id=#{publishedRevisionId}
WHERE id=#{recordId} AND status=#{fromStatus} AND version=#{expectedVersion}

UPDATE lab_experiment_revision
SET status=#{toStatus}, update_time=#{now}
, approved_by=#{actorId}, approved_at=#{now}
WHERE id=#{revisionId} AND status=#{fromStatus}

mapper.insert:
INSERT INTO lab_experiment_feedback(
    record_id, revision_id, feedback_type, content, visibility,
    reviewer_id, reviewer_name, request_id, create_time
) VALUES (
    #{recordId}, #{revisionId}, #{type}, #{content}, #{visibility},
    #{reviewerId}, #{reviewerName}, #{requestId}, #{createTime}
)

mapper.update:
UPDATE lab_experiment_revision
SET status='PUBLISHED', published_by=#{actorId}, published_at=#{now}, update_time=#{now}
WHERE id=#{revisionId} AND status='APPROVED'

mapper.select:
SELECT id, record_id AS recordId, revision_id AS revisionId, feedback_type AS type,
       content, visibility, reviewer_id AS reviewerId, reviewer_name AS reviewerName,
       create_time AS createTime
FROM lab_experiment_feedback
WHERE record_id=#{recordId} 
ORDER BY create_time DESC, id DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.insert:
INSERT IGNORE INTO lab_request_idempotency(
    actor_id, operation, idempotency_key, request_digest, status, create_time, update_time
) VALUES (#{actorId}, #{operation}, #{idempotencyKey}, #{requestDigest}, 'PROCESSING', #{now}, #{now})

mapper.select:
SELECT request_digest AS requestDigest, status, response_json AS responseJson
FROM lab_request_idempotency
WHERE actor_id=#{actorId} AND operation=#{operation} AND idempotency_key=#{idempotencyKey}

mapper.update:
UPDATE lab_request_idempotency
SET status='COMPLETED', response_code=200, response_json=#{responseJson}, update_time=#{now}
WHERE actor_id=#{actorId} AND operation=#{operation} AND idempotency_key=#{idempotencyKey}
  AND status='PROCESSING'

